"""Build the complete Week 6 unit. Existing response IDs and option tokens stay stable."""
from pathlib import Path
from html import escape
import json,os
ROOT=Path(__file__).resolve().parents[1]
NAV=[('Reading','readings/week6_reading.html'),('Explorer','demos/interest_loans.html'),('Laboratory','labs/week6_lab.html'),('Repayment','applications/week6_application.html'),('AI growth','applications/week6_ai.html'),('Discussion','discussions/week6_discussion.html')]
def write(path,text):
 p=ROOT/path;t=p.with_suffix(p.suffix+'.tmp')
 with t.open('w') as f:f.write(text);f.flush();os.fsync(f.fileno())
 os.replace(t,p)
def figure(name,alt,caption):return f'<figure class="figure"><img src="../assets/week6/{name}.svg" alt="{escape(alt,quote=True)}" loading="lazy"><figcaption>{caption}</figcaption></figure>'
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+str(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def quick(q,a):return '<div class="quick-check"><p>'+q+'</p><details><summary>Compare your reasoning</summary><p>'+a+'</p></details></div>'
def num(id,label,ans,hint,tol=.001):return f'<div class="question"><label for="{id}">{label}</label><input id="{id}" type="text" inputmode="decimal" autocomplete="off" data-answer="{ans}" data-tolerance="{tol}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def select(id,label,opts,ans,hint):return f'<div class="question"><label for="{id}">{label}</label><select id="{id}" data-answer="{ans}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><option value="">Choose a response…</option>'+''.join(f'<option value="{v}">{escape(t)}</option>' for v,t in opts)+f'</select><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def written(id,label):return f'<div class="question"><label for="{id}">{label}</label><textarea id="{id}" rows="5" data-save></textarea></div>'
def check():return '<div class="actions"><button type="button" data-check>Check this section</button></div><p class="section-feedback" aria-live="polite"></p>'
def progress():return '<div class="progress"><span id="progressText">0 sections checked</span><div class="progress-track" aria-hidden="true"><div class="progress-fill" id="progressFill"></div></div></div>'
def page(path,kind,title,lead,body,tags,store=None,legacy=None,nextlink=None):
 nav=''.join(f'<a href="../{url}"'+(' aria-current="page"' if url==path else '')+'>'+label+'</a>' for label,url in NAV)
 attrs=f' data-answer-store="{store}"'+(f' data-legacy-store="{legacy}"' if legacy else '') if store else ''
 end='<div class="student-bar"><div><label for="studentName">Your name for the printed copy</label><input id="studentName" autocomplete="name"></div><button type="button" data-print-work>Print / save completed work</button><div><p id="saveStatus" class="small save-status" aria-live="polite"></p><p id="printStatus" class="small" role="status"></p></div></div>' if store else '<div class="actions no-print"><button type="button" data-print-page>Print this page</button></div>'
 if nextlink:end+=f'<div class="next"><a href="../index.html">← Course home</a><a href="../{nextlink[1]}">{nextlink[0]} →</a></div>'
 s='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'<meta name="description" content="{escape(lead,quote=True)}"><title>Week 6 {kind} — {escape(title)} | Math in Society</title>'+r'''
<link rel="stylesheet" href="../assets/week6/week6.css"><script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><script defer src="../assets/week6/week6.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a href="../index.html">← MATH&amp; 107 · Math in Society</a><span>Centralia College · Dr Lee</span></header>'''+f'<nav class="unit-nav" aria-label="Week 6 materials">{nav}</nav><main class="wrap" id="main"{attrs}><header class="hero"><div class="eyebrow">Week 6 / {kind}</div><h1>{title}</h1><p class="lead">{lead}</p><div class="meta">'+''.join('<span class="tag">'+x+'</span>' for x in tags)+'</div></header>'+('<p class="print-name" id="printName"></p>' if store else '')+body+end+'<footer class="footer"><span>MATH&amp; 107 · Interest and Loans</span><a href="../readings/Math107_Chapter_07.pdf">Illustrated chapter, practice, and solutions ↗</a></footer></main></body></html>\n'
 write(path,s)

reading=r'''
<section class="card" id="start-here"><div class="kicker">The mathematical setting</div><h2>The same starting balance can follow different rules</h2><p>Suppose an account starts with $2,000. A rule adds 3% interest each year. Does that mean it adds $60 every year, or does it calculate 3% of the balance the account has reached? The first year looks the same, but the later years can differ.</p><p>Now imagine money owed on a loan. Interest increases the debt, while a payment decreases it. To understand the loan, we need to know which balance the interest uses, when the payment happens, and what remains for the next month.</p><p>Week 5 introduced a system’s <em>state</em> and an update rule. Our state this week is a balance, measured in dollars. Each ending balance becomes the next period’s starting state. We will use tables, graphs, and repeated arithmetic to see how the rule shapes the outcome. All rates and balances in the examples are hypothetical.</p><div class="grid"><div><h3>Build the model</h3><ul><li>Convert percentages and match rates to periods.</li><li>Distinguish fixed additions from compound growth.</li><li>Read formulas as repeated balance updates.</li></ul></div><div><h3>Interpret the outcome</h3><ul><li>Estimate a doubling time and check its meaning.</li><li>Separate interest from principal reduction.</li><li>Compare a payment, payoff time, and total interest.</li></ul></div></div><p>Read in order and work the short checks before revealing their explanations. The <a href="../demos/interest_loans.html">interest and loan explorer</a> makes both kinds of change visible. The <a href="Math107_Chapter_06.pdf">illustrated chapter</a> includes review exercises and complete solutions. The core calculations need arithmetic, powers, and simple equations.</p></section>
<nav class="toc card" aria-label="In this reading"><h2>Your route through the week</h2><ol><li><a href="#rates">Read a percentage, a balance, and a period</a></li><li><a href="#simple">Add interest based on the original amount</a></li><li><a href="#compound">Apply a percentage to the current balance</a></li><li><a href="#frequency">Match the rate and the number of updates</a></li><li><a href="#doubling">Use the Rule of 72 as an estimate</a></li><li><a href="#loans">Add interest, then subtract a payment</a></li><li><a href="#paymentparts">Separate interest and principal reduction</a></li><li><a href="#payoff">Follow a loan to its actual final payment</a></li><li><a href="#threshold">Test whether a payment reduces the balance</a></li><li><a href="#decisions">Compare outcomes and check the assumptions</a></li></ol></nav>
<section class="card" id="rates"><div class="kicker">1 / Start with the units</div><h2>A rate needs an amount to act on and a period to describe</h2><p><em>Principal</em> means the initial amount deposited or borrowed. We use P for that starting amount and B for a balance as it changes. A <em>period</em> is one update interval, such as a year or month. Year 0 records the initial balance, before any annual interest is added.</p><p>A percentage means “per hundred.” To calculate 3% of $2,000, first write \(3\%=3/100=0.03\), then multiply: \(0.03(2000)=60\) dollars. To keep the original money and add that interest, multiply by \(1+0.03=1.03\).</p>'''+figure('percent-and-factor','A grid has 100 cells, with 3 shaded to represent 3%. At $20 per cell, those cells represent $60 of a $2000 starting balance. The resulting balance is $2060.','The rate 0.03 gives the interest portion. The factor 1.03 keeps the original balance and adds 3% to it.')+table(['Expression','Meaning','For a $2,000 balance'],[['0.03B','3% of the balance','Interest of $60'],['B + 0.03B','Keep the balance and add its interest','New balance $2,060'],['1.03B','The same update written as multiplication','New balance $2,060']])+r'''<p>“3% per year” and “3% per month” describe different updates. In a formula, use a decimal rate whose time unit matches the period. Also keep separate the <em>interest amount</em> and the <em>total balance</em>: earning $60 does not mean the whole account is worth $60.</p><div class="example"><h3>Example · Read the notation before calculating</h3><p>\(B_0=2000\) names the starting balance. \(B_1\) means the balance after one update, and \(B_2\) after two. The small number is a period label, not a multiplier. The rule \(B_{k+1}=1.03B_k\) says “multiply the current balance by 1.03 to get the next one.”</p></div>'''+quick('A $500 balance earns 4% for one period. What is the interest, the growth factor, and the new balance?','The decimal rate is 0.04, interest is 0.04(500)=$20, the factor is 1.04, and the new balance is $520.')+r'''</section>
<section class="card" id="simple"><div class="kicker">2 / The original principal stays the reference</div><h2>Simple interest adds the same dollar amount each year</h2><p>With <em>simple interest</em>, interest is calculated on the original principal, not on the accumulated balance. Start at P=$2,000 with annual rate r=0.03. Each year adds the same \(Pr=60\) dollars.</p>'''+figure('simple-updates','Annual simple-interest balances from year 0 through 5 are 2000, 2060, 2120, 2180, 2240, and 2300 dollars. Every step adds 60 dollars.','The equal dollar steps make a straight-line pattern. The year-5 balance includes the original $2,000 plus five $60 additions.')+r'''<p>After t years, interest is \(I=Prt\), and total amount is</p><div class="formula">\[A=P+Prt=P(1+rt).\]</div><p>The formula collects the repeated additions into one calculation. With annual updates, we can also write \(B_{k+1}=B_k+Pr\): the constant step Pr is added to the current total, but calculated from the <em>original</em> principal.</p><div class="example"><h3>Example · Evaluate and solve backward</h3><p>After five years, \(A=2000(1+0.03\cdot5)=2300\) dollars. The interest earned is \(2300-2000=300\) dollars.</p><p>Suppose instead a simple-interest account grows from $500 to $560 in four years. The $60 gain is $15 per year. Dividing $15 by the $500 original amount gives \(r=0.03\), or 3% per year. Algebra gives the same answer: \(560/500-1=4r\), so \(r=0.12/4=0.03\).</p></div><p>If time is given in months while r is annual, convert months to years. Under a proportional simple-interest model, six months is t=0.5 year; $2,000 at 3% earns \(2000(0.03)(0.5)=30\) dollars over that time.</p>'''+quick('An account starts at $900 and earns 4% simple annual interest. What is the fixed yearly increase and the total after three years?','The increase is 900(0.04)=$36 per year. After three years, the total is 900+3(36)=$1,008. The $108 gain is interest, not the total balance.')+r'''</section>
<section class="card" id="compound"><div class="kicker">3 / The current balance sets the next increase</div><h2>Compound interest lets earlier interest earn interest</h2><p>With <em>compound interest</em>, each update calculates interest on the balance reached so far. At 3% annually, $2,000 becomes $2,060 after one year. The second year’s interest is \(0.03(2060)=61.80\), so the next balance is $2,121.80.</p><p>The annual rule is \(B_{k+1}=(1+r)B_k\). Applying it repeatedly gives</p><div class="formula">\[B_1=P(1+r),\quad B_2=P(1+r)^2,\quad A=P(1+r)^t.\]</div><p>The exponent counts repeated multiplications. For three years, multiply by 1.03 three times; do not replace this by adding 3% of the original amount three times.</p>'''+figure('compound-updates','One panel shows annual compound balances from 2000 to 2318.55 dollars over five years at 3%. The other shows annual interest increasing from 60 to about 67.53 dollars.','The percentage stays at 3%, while its dollar base grows. Table and chart values round for display; the compound formula keeps precision until the final answer.')+table(['Year','Simple balance ($)','Annual compound balance ($)'],[['0','2,000.00','2,000.00'],['1','2,060.00','2,060.00'],['2','2,120.00','2,121.80'],['3','2,180.00','2,185.45'],['4','2,240.00','2,251.02'],['5','2,300.00','2,318.55']])+r'''<p>At the same positive annual rate, the two models agree after the first annual update. Later, compounding uses the earlier interest as part of its base. At 30 years, the simple model gives $3,800, while the annual compound model gives about $4,854.52.</p>'''+figure('growth-over-time','At $2000 and a 3% annual rate, simple interest reaches 3800 dollars after 30 years and annual compound interest reaches about 4854.52.','Dots record balances at annual updates; connecting lines help compare the patterns. A gently increasing percentage process can accumulate a substantial difference over many periods.')+r'''<div class="insight"><h3>A curve and a schedule are different parts of a model</h3><p>The balance table records specified crediting dates. A continuous curve can help us visualize the growth pattern between them, but the account’s terms determine when interest is actually credited. Our explorer uses whole years and specified compounding periods, so the displayed endpoints are completed updates.</p></div>'''+quick('Start with $300 at 10% compounded annually. Find the first and second yearly balances, and compare with two years of simple interest.','The balances are 300(1.10)=$330 and 330(1.10)=$363. Simple interest gives 300+2(30)=$360. The extra $3 comes from interest on the first year’s $30 interest.')+r'''</section>
<section class="card" id="frequency"><div class="kicker">4 / Match the rate to each update</div><h2>Monthly compounding changes both the rate and the count</h2><p>Suppose a model quotes a nominal annual rate r=0.06 and compounds 12 times a year. The rate per monthly update is \(i=r/12=0.005\), which is 0.5%, not 6%. Over ten years there are \(12(10)=120\) monthly updates.</p><p>For n equal compounding periods per year and t years, the formula is</p><div class="formula">\[A=P\left(1+\frac{r}{n}\right)^{nt}.\]</div><p>Read the inside and outside together: r/n is the rate for one step, and nt is the number of steps. Using a monthly rate with an annual count would model a different amount of time.</p><div class="example"><h3>Example · Write the substituted expression first</h3><p>For $1,000 at 6% nominal annual interest compounded monthly for ten years:</p><p>\[A=1000\left(1+\frac{0.06}{12}\right)^{120}=1000(1.005)^{120}\approx1819.40.\]</p><p>Use parentheses around the full factor and keep the calculator’s precision through the exponent. The final interest earned is approximately $819.40.</p></div>'''+figure('compounding-frequency','Interest earned on $1000 at 6% nominal annual interest over ten years is about 790.85 annually, 806.11 semiannually, 814.02 quarterly, 819.40 monthly, and 822.03 daily.','The bars show interest earned, not the whole account balance. The comparison holds the nominal annual rate fixed. Daily means 365 equal periods in this constructed model.')+r'''<p>For these positive rates, more frequent compounding increases the final amount, with smaller extra gains as the frequencies increase. This comparison does not hold the effective annual yield fixed.</p><h3>The effective annual yield describes a whole year’s growth</h3><p>The <em>effective annual yield</em> is the fraction gained over one year, including compounding. For a 3% nominal annual rate compounded monthly,</p><p>\[\left(1+\frac{0.03}{12}\right)^{12}-1\approx0.030416,\]</p><p>or about 3.0416%. The decimal 0.030416 and the percentage 3.0416% describe the same yield. The nominal rate 3% and the effective yield answer different questions about the update rule.</p>'''+quick('For a nominal annual rate of 12%, compounded monthly for two years, give the decimal monthly rate and the number of updates.','The monthly rate is 0.12/12=0.01, or 1%. There are 12(2)=24 updates, so the growth factor over the full time is (1.01)^24.')+r'''</section>
<section class="card" id="doubling"><div class="kicker">5 / An estimate with a specific meaning</div><h2>The Rule of 72 estimates repeated percentage growth</h2><p>For a positive balance growing at a fixed positive annual compound rate, the <em>Rule of 72</em> estimates the years needed to double:</p><div class="formula">\[\text{doubling time}\approx\frac{72}{\text{annual rate written as a percentage number}}.\]</div><p>At 6%, use 72/6=12 years. Do not divide by 0.06. At 9%, the estimate is eight years. These are estimates under a continuing growth rule, not guaranteed future returns.</p>'''+figure('doubling-estimates','With 6% annual compounding, a starting amount grows to about 2.012 times itself after 12 years and 4.049 times itself after 24 years.','About 12 years produces one doubling, and about 24 produces two doublings. Two doublings multiply the starting amount by four, not by three.')+r'''<div class="example"><h3>Example · Check the estimate using powers</h3><p>At 6% annual compounding, \((1.06)^{11}\approx1.898\) and \((1.06)^{12}\approx2.012\). The first completed annual update reaching twice the starting balance is year 12. The Rule of 72 is a useful scale estimate; it is not an equation making the balance exactly double at year 12.</p></div><p>The same reasoning works for invented compute capacity or another quantity following a fixed percentage rule. It does not describe simple interest, and it does not by itself describe a loan being reduced by payments. At a zero growth rate, a positive starting amount never doubles through this rule.</p>'''+quick('Use the Rule of 72 to estimate doubling time at 8% and quadrupling time at 6%.','At 8%, one doubling takes about 72/8=9 years. At 6%, one doubling takes about 12 years, so quadrupling takes about 24 years if the rate and compounding assumptions continue.')+r'''</section>
<section class="card" id="loans"><div class="kicker">6 / Interest first, payment second</div><h2>A payment subtracts from a balance that has just grown</h2><p>In our loan model, interest is added once a month, then the scheduled payment is applied. Let B be the balance at the start of that month, i the monthly decimal rate, and M the regular payment in dollars.</p><div class="formula">\[\text{interest}=iB,\qquad B_{\text{next}}=B+iB-M=(1+i)B-M.\]</div><p>The annual rate r is divided by 12 <em>under the stated monthly model</em>, so i=r/12. A $4,000 loan at a 6% nominal annual rate uses i=0.06/12=0.005, or 0.5% per month. The first interest charge is $20. In credit-card terminology, APR stands for <em>annual percentage rate</em>; our card exercises explicitly specify the monthly conversion used in their simplified model.</p>'''+figure('loan-one-month','A $4000 loan grows by $20 interest to $4020, then a $200 payment reduces the amount owed to $3820.','The $200 payment covers $20 interest and reduces principal by $180. The ending balance $3,820 becomes the next month’s starting balance.')+r'''<div class="example"><h3>Example · Repeat using the new balance</h3><p>Month 1: \(4000(1.005)-200=3820\). Month 2 starts at $3,820, so its interest is \(3820(0.005)=19.10\) dollars. After the next $200 payment, the balance is \(3820+19.10-200=3639.10\).</p><p>Using $4,000 again in month 2 would incorrectly keep charging the original interest amount. The current balance is part of the rule.</p></div><div class="insight"><h3>The credit-card examples use a simplified schedule</h3><p>Our activities use fixed rates, no new purchases or fees, and one interest calculation followed by one payment each month. The <a href="https://www.consumerfinance.gov/ask-cfpb/how-does-my-credit-card-company-calculate-the-amount-of-interest-i-owe-en-51/">Consumer Financial Protection Bureau explains</a> that many real card issuers use daily balance calculations. The monthly model makes the repeated arithmetic visible; actual statements follow their account terms.</p></div>'''+quick('A $500 loan balance has 2% interest for one period, then a $60 payment. Find the interest, principal reduction, and ending balance.','Interest is 0.02(500)=$10. The payment reduces principal by 60−10=$50. Ending balance is 500+10−60=$450.')+r'''</section>
<section class="card" id="paymentparts"><div class="kicker">7 / Read each payment in two parts</div><h2>Interest and principal reduction add up to the actual payment</h2><p>For the decreasing loan above, the monthly payment stays $200, but its parts change. A smaller starting balance generates less interest. More of the same payment can then reduce what is owed.</p>'''+figure('payment-parts','Stacked $200 payment bars for months 1, 5, 10, and 20 split into a shrinking interest part and a growing principal-reduction part.','The whole bar is the payment. Its interest portion is a cost of borrowing for that month; the remainder reduces the debt. These bars come from the $4,000, 6%, $200-payment model.')+table(['Month','Start balance ($)','Interest ($)','Payment ($)','End balance ($)'],[['1','4,000.00','20.00','200.00','3,820.00'],['2','3,820.00','19.10','200.00','3,639.10'],['3','3,639.10','18.20','200.00','3,457.30'],['4','3,457.30','17.29','200.00','3,274.59']])+r'''<p>A table of this repeated repayment calculation is often called an <em>amortization schedule</em>. Check each row by adding interest to the start balance and subtracting the actual payment. The next row must begin with the previous row’s ending balance.</p><div class="insight"><h3>State the rounding rule</h3><p>The loan table in this reading rounds each month’s interest to the nearest cent before updating the balance. The application’s long comparison keeps full internal precision and rounds only the displayed results, preserving its original calculation method. Both conventions are available in the explorer. Small total differences can come from rounding rather than from a different interest formula.</p></div>'''+quick('In a month with $16.37 interest and a $200 actual payment, how much reduces principal? What would have to change for the next month’s interest to be smaller?','Principal reduction is 200−16.37=$183.63. Under a fixed positive rate, reducing the balance makes the next interest charge smaller; the rate itself does not need to change.')+r'''</section>
<section class="card" id="payoff"><div class="kicker">8 / Count the whole repayment path</div><h2>The final payment is the amount still due</h2><p>Continue the $4,000 loan at 6% with $200 monthly payments, rounding monthly interest to cents. After 21 regular payments, $24.87 remains. Month 22 adds $0.12 interest, so the final amount due is $24.99. Paying that amount closes the loan.</p><p>We do not subtract the full scheduled $200 and report a negative debt. The actual last payment is the smaller of the regular payment and the amount due.</p><div class="example"><h3>Example · Total paid and total interest</h3><p>\[\text{total paid}=21(200)+24.99=4224.99,\]</p><p>\[\text{total interest}=4224.99-4000=224.99.\]</p><p>The total paid includes the $4,000 originally borrowed. The amount above that principal is the interest in this model, since there are no other fees or charges.</p></div>'''+figure('repayment-paths','Three paths for a $4000 loan at 6% show payoff in 29 months with $150 payments, 22 months with $200, and 14 months with $300, using cent-rounded monthly interest.','The curves share the same starting balance and first-month interest rate. Different payments create different later balances, which change later interest.')+table(['Regular payment','Payoff month','Total paid ($)','Total interest ($)'],[['$150','29','4,303.84','303.84'],['$200','22','4,224.99','224.99'],['$300','14','4,150.01','150.01']])+r'''<p>For these otherwise identical fixed-rate loans, larger payments reduce the balance faster and leave less balance on which later interest is charged. They also require more money each month. The table quantifies that tradeoff; it does not tell us what a household can afford.</p>'''+quick('A loan starts at $2,000. Its payments total $2,180, including a smaller final payment. With no fees or new borrowing, how much interest was paid? Why is $2,180 not all interest?','Total interest is 2180−2000=$180. The other $2,000 repays the principal originally borrowed.')+r'''</section>
<section class="card" id="threshold"><div class="kicker">9 / Compare payment with this month’s interest</div><h2>Growing, unchanged, and decreasing are different outcomes</h2><p>A payment does not automatically make a debt smaller. From \(B_{\text{next}}-B=iB-M\), compare M with the interest iB. If the payment is larger, the balance falls. If it is equal, the balance stays the same. If it is smaller, the balance grows.</p>'''+figure('payment-threshold','A $1000 balance at 1% monthly interest is compared under payments $5, $10, and $50. Over twelve months the first grows, the second stays at 1000, and the third falls.','The first interest charge is $10 for all three plans. A $10 payment covers that interest exactly and leaves the original $1,000 unchanged; it does not pay the loan off.')+r'''<p>With a fixed rate, fixed payment, and no new charges, a payment exceeding the initial monthly interest makes the balance decrease. Later interest is then no larger, so the same payment continues reducing the balance. In a fixed-rate model, this leads to eventual payoff; a calculator still needs enough periods to display the full path.</p><p>If a simulation stops at a chosen horizon, such as 1,200 months, an outstanding balance means “not paid within this horizon.” It must not label the stopping month as payoff. At zero interest, a positive payment reduces the loan by a fixed amount each month; a zero payment leaves it unchanged.</p>'''+quick('An $8,000 balance has a 1.5% monthly rate. Classify payments of $100, $120, and $160 using the first interest charge.','The first interest is 8000(0.015)=$120. A $100 payment leaves the balance growing, $120 leaves it unchanged, and $160 reduces it by $40 in month 1, under the fixed-rate monthly model.')+r'''</section>
<section class="card" id="decisions"><div class="kicker">10 / Ask which outcome matters</div><h2>A useful comparison includes the path, the totals, and the assumptions</h2><p>A monthly payment, payoff time, and total interest answer different questions. For a borrower, the payment describes the current monthly commitment and the total describes its long-run modeled cost. A lender can use the same schedule to calculate payments received and interest collected. The underlying arithmetic is shared.</p><p>When comparing plans, name the starting principal, rate per period, timing of payments, rounding rule, and whether new purchases or fees are included. Then report what the model actually computes. Changing one assumption gives a new scenario, not a correction to a fact about every loan.</p><div class="example"><h3>Example · A complete comparison statement</h3><p>“For a $4,000 balance at 6% nominal annual interest with monthly updates, no additional charges, and cent-rounded monthly interest, $300 payments give payoff in month 14 and $150.01 total interest. With $150 payments, payoff is month 29 and interest is $303.84.” This states both the result and the conditions supporting it.</p></div><ol class="steps"><li>Define the balance and the time unit.</li><li>Match the decimal rate to that unit.</li><li>Calculate one update by hand before using a formula or calculator.</li><li>Trace enough periods to answer the question.</li><li>Separate the ending balance, interest, payments, and total cost.</li><li>State a comparison and an assumption worth checking.</li></ol><div class="insight"><h3>Prepare for Week 7</h3><p>Week 7 compares costs, revenue, and profit for different possible quantities. The habit remains the same: define the input and units, name the outcome of interest, state the available choices, and interpret the result in context. Here the input is time; there it will often be quantity for one event or month.</p></div><p>Practice in the <a href="../labs/week6_lab.html">laboratory</a>, compare the two <a href="../applications/week6_application.html">repayment plans</a>, and explore <a href="../applications/week6_ai.html">hypothetical compute growth</a>. The <a href="../discussions/week6_discussion.html">discussion</a> asks you to show and explain a payment schedule.</p></section>
<section class="card" id="sources"><h2>Further reading and model context</h2><p><a href="https://www.investor.gov/additional-resources/information/youth/teachers-classroom-resources/what-compound-interest">Investor.gov: compound interest and the Rule of 72</a> provides an official educational introduction. Its <a href="https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator">compound-interest calculator</a> also includes optional contributions; our basic comparison holds contributions at zero.</p><p>The <a href="https://www.consumerfinance.gov/ask-cfpb/how-does-my-credit-card-company-calculate-the-amount-of-interest-i-owe-en-51/">CFPB’s interest-calculation explanation</a> describes why actual card statements can differ from our monthly model. The examples and graphics in this unit are constructed for learning.</p></section>
'''
page('readings/week6_reading.html','Reading','Interest and loans: follow the changing balance.','See how a percentage, a period, and an update rule turn a starting amount into a savings path or a repayment schedule.',reading,['Percentages with units','Annotated graphics','Worked updates & short checks'],nextlink=('Try the interest and loan explorer','demos/interest_loans.html'))

explorer=r'''
<section class="card"><h2>Predict one change, then inspect the result</h2><p>The savings model starts with one deposit, no later deposits or withdrawals, and a fixed nonnegative nominal annual rate. The loan model adds interest once per month and applies a payment afterward, with no new borrowing or fees. All rates here are hypothetical.</p><p><a href="#savings">Compare savings growth</a> or <a href="#repayment">investigate loan repayment</a>. Every graph is accompanied by numerical values. Enter dollars without a dollar sign, and enter annual rates as percentage numbers: use 6 for 6%, not 0.06.</p></section>
<section class="card" id="savings"><div class="kicker">Explore / A deposit with two growth rules</div><h2>Compare fixed additions with compounding</h2><div class="controls"><div><label for="sP">Starting principal ($)</label><input id="sP" type="number" min="0" max="1000000" step="0.01" value="2000"></div><div><label for="sr">Nominal annual rate (%)</label><input id="sr" type="number" min="0" max="30" step="0.01" value="3"></div><div><label for="st">Whole years</label><input id="st" type="number" min="0" max="40" step="1" value="5"></div><div><label for="sn">Compound periods per year</label><select id="sn"><option value="1">1 — annually</option><option value="2">2 — semiannually</option><option value="4">4 — quarterly</option><option value="12">12 — monthly</option><option value="365">365 — daily in this model</option></select></div></div><p id="savingsError" class="chart-error" role="status"></p><div id="savingsResults"><p id="savingsModel" class="formula"></p><div class="stats"><div class="stat"><span>Simple final balance</span><output id="simpleOut"></output></div><div class="stat"><span>Compound final balance</span><output id="compoundOut"></output></div><div class="stat"><span>Compound minus simple</span><output id="diffOut"></output></div></div><p id="savingsSummary" class="readout" aria-live="polite"></p><div class="chart" id="savingsPlot">'''+figure('growth-over-time','Simple and annual compound models starting at $2000 with a 3% annual rate diverge over 30 years.','Enable JavaScript to graph the current inputs and inspect the year-by-year table.')+r'''</div><p class="small">Teal is compound growth and rust is simple growth. Annual markers show completed years. Connecting lines guide the eye; the compounding schedule determines the update dates. The vertical axis starts at zero.</p><div class="table-wrap trace" id="savingsTable"></div><p id="savingsYield" class="readout"></p><p id="savingsDoubling" class="readout"></p></div></section>
<section class="card" id="repayment"><div class="kicker">Explore / A monthly debt update</div><h2>Follow interest and payments to the final balance</h2><div class="controls"><div><label for="loanPreset">Starting loan model</label><select id="loanPreset"><option value="reading">Reading: $4,000 at 6%, pay $200</option><option value="lab">Lab: $3,000 at 9%, pay $150</option><option value="cardA">Application A: $8,000 at 18%, pay $160</option><option value="cardB">Application B: $8,000 at 18%, pay $300</option><option value="discussion">Discussion: $5,000 at 18%, pay $225</option><option value="flat">Interest exactly covered</option><option value="growing">Payment below interest</option><option value="zero">Zero-interest loan</option></select></div><div><label for="lP">Starting loan balance ($)</label><input id="lP" type="number" min="0" max="1000000" step="0.01" value="4000"></div><div><label for="lr">Nominal annual rate (%)</label><input id="lr" type="number" min="0" max="40" step="0.01" value="6"></div><div><label for="lpay">Regular monthly payment ($)</label><input id="lpay" type="number" min="0" max="1000000" step="0.01" value="200"></div><div><label for="loanRounding">Rounding rule</label><select id="loanRounding"><option value="cents">Round monthly interest to cents</option><option value="full">Keep full internal precision</option></select></div><div><label for="loanHorizon">Maximum months to simulate</label><input id="loanHorizon" type="number" min="1" max="1200" step="1" value="1200"></div></div><p id="loanError" class="chart-error" role="status"></p><div id="loanResults"><p id="loanModel" class="formula"></p><div class="stats"><div class="stat"><span>First month’s interest</span><output id="loanFirst"></output></div><div class="stat"><span>First actual payment</span><output id="loanActual"></output></div><div class="stat"><span>First principal reduction</span><output id="loanReduction"></output></div></div><p id="loanSummary" class="readout" aria-live="polite"></p><p id="loanTotals" class="readout"></p><div class="chart" id="loanPlot">'''+figure('repayment-paths','The same $4000 loan follows different repayment paths with $150, $200, and $300 monthly payments.','Enable JavaScript to graph the selected loan’s path.')+r'''</div><p id="loanPlotNote" class="small"></p><h3>Monthly repayment table</h3><div class="controls"><div><label for="showAllMonths"><input id="showAllMonths" type="checkbox"> Show all simulated months</label></div></div><p class="small">By default the table shows the first six months and the last simulated month. The last row is a payoff only when its ending balance is zero. An unchanged balance and a growing balance have different result statements.</p><div class="table-wrap trace" id="loanTable"></div></div></section>
<section class="card"><h2>Five investigations</h2><ol class="steps"><li>For savings at $2,000 and 3%, compare years 1, 5, and 30 with annual compounding. Why do the first-year amounts tie?</li><li>Set principal $1,000, annual rate 6%, and ten years. Change only compounding frequency. Compare the effective yield with the quoted nominal rate.</li><li>For the reading’s loan, compare month 1 with month 5. Which part of the $200 payment changes, and why?</li><li>Choose interest exactly covered, then payment below interest. Explain the distinction between a constant debt and a growing debt. In each case, what does the payment cover?</li><li>Return to the reading’s loan and limit the simulation to six months. Explain why six is not its payoff month. Then restore a long enough horizon and compare the two rounding methods.</li></ol><p>For the application’s original comparison results, select its presets and keep full internal precision. For the reading, lab’s hand table, and discussion, use monthly cent rounding. The difference is part of the model and is stated with each result.</p><div class="insight"><h3>A model of a schedule</h3><p>The rate is fixed, payment happens after interest, and there are no new charges. Actual financial products can use different timing and calculation rules. Use the displayed assumptions to interpret this classroom comparison.</p></div></section><noscript><section class="card"><p>The controls need JavaScript. The reading and chapter give complete graphs, tables, and worked calculations for the starting models.</p></section></noscript>
'''
page('demos/interest_loans.html','Explorer','Watch the balance become the next input.','Compare savings growth, then trace a loan through interest, actual payments, principal reduction, and payoff.',explorer,['Savings & repayment','Explicit rounding choices','Graphs with numerical tables'],nextlink=('Practice the calculations','labs/week6_lab.html'))

lab=r'''
<section class="card"><h2>Keep the rate, period, and balance together</h2><p>For each exercise, identify the starting amount, decimal rate, and number of updates before calculating. Enter money without a dollar sign. For formula-based savings questions, keep precision until the final answer and round money to cents. The loan table in Part 5 rounds each month’s interest to cents before updating.</p><p>Use \(A=P(1+rt)\) for simple interest and \(A=P(1+r/n)^{nt}\) for compound interest. In both, r is an annual <em>decimal</em> rate. When a field asks for a percentage, enter the percentage number instead: for example, enter 3 for 3%. The <a href="../demos/interest_loans.html">explorer</a> lets you check the same rules.</p><p>Your numerical responses receive individual feedback. Written explanations save and print for instructor review. The progress count tracks the five graded sections.</p></section>'''+progress()+r'''
<section class="card" data-check-group="1"><div class="kicker">Part 1 / Constant dollar additions</div><h2>Simple interest and missing information</h2><div class="example"><h3>Worked example · A different starting amount</h3><p>A $600 account at 5% simple annual interest adds $30 each year. Four years adds $120, so the total is $720. To find an unknown rate, divide the interest earned by principal times years. To find time, divide interest earned by the fixed yearly interest.</p></div><div class="grid">'''+num('p1a','Balance: $1,500 at 4% simple interest for 3 years ($)',1680,'Use 1500(1+0.04×3).',.02)+num('p1b','Balance: $800 at 6% simple interest for 5 years ($)',1040,'Use 800(1+0.06×5).',.02)+num('p1c','$4,000 grows to $4,600 in 5 simple-interest years: annual rate (%)',3,'Find the $600 gain, then divide by 4000×5 and convert the decimal to percent.',.01)+num('p1d','$2,500 at 4% simple interest reaches $3,000 after how many years?',5,'Divide the $500 gain by the fixed yearly interest 2500×0.04.',.01)+num('p1e','$1,200 at 5% simple interest: yearly increase ($)',60,'Multiply the original 1200 by 0.05.',.02)+num('p1f','Same $1,200 account: balance after 6 years ($)',1560,'Add six yearly increases to the original balance.',.02)+r'''</div>'''+written('simpleReason','Explain why simple interest on the $1,200 account adds the same dollar amount even after its total balance has increased.')+check()+r'''</section>
<section class="card" data-check-group="2"><div class="kicker">Part 2 / Repeated multiplication</div><h2>Count the factors before using the calculator</h2><p>Annual compounding uses one factor per year. Monthly compounding uses rate r/12 and twelve times as many factors. For example, $400 at 10% annually becomes $440 and then $484 over two years. A fixed $40 addition each year would instead give $480.</p><div class="grid">'''+num('p2a','$1,000 at 5%, compounded annually for 4 years ($)',1215.51,'Use 1000(1.05)^4, then round the final result.',.02)+num('p2b','$500 at 8%, compounded annually for 3 years ($)',629.86,'Use 500(1.08)^3.',.02)+num('p2c','$2,000 at 4%, compounded monthly for 6 years ($)',2541.48,'Use 2000(1+0.04/12)^72.',.03)+r'''</div><p>Now compare three models for the same $1,500 at 6% for ten years. Hold the starting amount, nominal annual rate, and duration fixed.</p><div class="grid">'''+num('p2d','Simple-interest final balance ($)',2400,'Use 1500(1+0.06×10).',.02)+num('p2e','Annual-compound final balance ($)',2686.27,'Use 1500(1.06)^10.',.03)+num('p2f','Monthly-compound final balance ($)',2729.10,'Use 1500(1.005)^120.',.03)+select('p2g','Order the three balances from smallest to largest',[('s-a-m','simple, annual compound, monthly compound'),('m-a-s','monthly compound, annual compound, simple'),('a-s-m','annual compound, simple, monthly compound')],'s-a-m','Compare the three amounts you calculated; all use the same nominal annual rate.')+r'''</div>'''+written('compoundReason','Write the monthly rate and update count for the six-year question. Explain what the exponent 72 counts.')+check()+r'''</section>
<section class="card" data-check-group="3"><div class="kicker">Part 3 / Rate per step and steps per year</div><h2>Compounding frequency and effective yield</h2><p>Use a $1,000 principal, 6% nominal annual rate, and ten years. For daily compounding in this exercise, use exactly 365 equal periods per year. Keep internal precision until the final balance.</p><div class="grid">'''+num('p3a','Annual compounding: final balance ($)',1790.85,'Use n=1 and exponent 10.',.03)+num('p3b','Monthly compounding: final balance ($)',1819.40,'Use n=12 and exponent 120.',.03)+num('p3c','Daily compounding: final balance ($)',1822.03,'Use n=365 and exponent 3650.',.03)+num('p3d','Number of monthly updates in 10 years',120,'Multiply years by 12 months per year.',.01)+num('p3e','Monthly periodic rate for a 6% nominal annual rate (%)',.5,'Divide 6 percentage points by 12; this field asks for percent, not decimal.',.001)+num('p3f','3% nominal annual rate, monthly compounding: effective annual yield (%)',3.0416,'Compute ((1+0.03/12)^12−1)×100.',.005)+select('p3g','Which statement matches the frequency comparison?',[('diminish','More frequent compounding increases the balance, but the extra gain becomes smaller.'),('linear','Each increase in frequency adds the same dollar amount.'),('same','Compounding frequency has no effect.')],'diminish','The nominal rate stays fixed while the number of smaller updates increases.')+r'''</div>'''+written('frequencyReason','Explain the difference between the decimal monthly rate 0.005 and the percentage monthly rate 0.5%. Why is neither 6% per month?')+check()+r'''</section>
<section class="card" data-check-group="4"><div class="kicker">Part 4 / Estimate, then interpret</div><h2>Doubling and two doublings</h2><p>Use the Rule of 72: divide 72 by the annual percentage number. These questions assume fixed percentage growth continues without withdrawals or payments. The answers are estimates in years, except the field asking for a rate.</p><div class="grid">'''+num('p4a','4% annual growth: estimated doubling time (years)',18,'Compute 72/4.',.01)+num('p4b','8% annual growth: estimated doubling time (years)',9,'Compute 72/8.',.01)+num('p4c','12% annual growth: estimated doubling time (years)',6,'Compute 72/12.',.01)+num('p4d','2% annual growth: estimated doubling time (years)',36,'Compute 72/2.',.01)+num('p4e','Estimated doubling time 9 years: annual rate (%)',8,'Solve 9≈72/r%, keeping r% as a percentage number.',.01)+num('p4f','6% annual growth: estimated time to quadruple (years)',24,'Four times the original amount requires two doublings.',.01)+r'''</div>'''+written('doublingReason','Would the Rule of 72 alone predict payoff time for a loan with monthly payments? Explain using the difference between its growth rule and a savings growth rule.')+check()+r'''</section>
<section class="card" data-check-group="5"><div class="kicker">Part 5 / Carry the ending balance forward</div><h2>A $3,000 loan with $150 monthly payments</h2><p>The nominal annual rate is 9%, divided across twelve monthly updates. Thus \(i=0.09/12=0.0075\), or 0.75% monthly. Interest is added first, then $150 is paid. There are no additional charges.</p><p>Round each month’s interest to cents, subtract the payment, and carry the resulting cent balance into the next row. The provided starting balances help you check continuity; they are not all $3,000.</p>'''+table(['Month','Start balance ($)','Operation'],[['1','3,000.00','Interest = start × 0.0075; end = start + interest − 150'],['2','2,872.50','Use the new starting balance'],['3','2,744.04','Repeat the same rule'],['4','2,614.62','Repeat the same rule']])+r'''<div class="grid">'''+''.join(num('p5i'+str(n),f'Month {n}: interest ($)',i,'Multiply that row’s starting balance by 0.0075, then round to cents.',.02)+num('p5b'+str(n),f'Month {n}: balance after payment ($)',b,'Add the rounded interest to the starting balance, then subtract $150.',.03) for n,i,b in [(1,22.50,2872.50),(2,21.54,2744.04),(3,20.58,2614.62),(4,19.61,2484.23)])+num('p5p','Month 1: part of the $150 payment reducing principal ($)',127.50,'Subtract month-1 interest from the actual payment.',.02)+select('p5s','Same starting balance and rate, different payments: which has the same first-month interest?',[('both','both loans'),('larger','only the larger-payment loan'),('smaller','only the smaller-payment loan')],'both','Interest is calculated before the payments, using the same balance and rate.')+r'''</div>'''+written('loanReason','Explain why later interest charges can differ under the two payment amounts even though the first charges agree. Refer to the next month’s starting balance.')+check()+r'''</section><section class="card"><h2>Review your work</h2><p>Check percentage versus decimal entries, starting amounts versus final balances, and interest versus payments. Add your name below and print or save your completed work as directed by your instructor. Written explanations save with the numerical responses, but are not automatically graded.</p></section>
'''
page('labs/week6_lab.html','Laboratory','Growth, interest, and loan updates.','Work from one period’s arithmetic to a complete growth rule, then track how interest and payments change the next balance.',lab,['Five guided investigations','Feedback for every answer','Saved work & named printing'],store='math107_week6_lab_v3',legacy='math107_week6_lab_v2',nextlink=('Compare the two repayment plans','applications/week6_application.html'))

application=r'''
<section class="card"><div class="kicker">The setting / Two fixed payment schedules</div><h2>An $8,000 balance with one monthly interest update</h2><p>A hypothetical borrower owes $8,000. Use a fixed 18% nominal annual rate, divided across twelve monthly updates, so \(i=0.18/12=0.015=1.5\%\) per month. There are no new purchases, fees, or rate changes. Interest is added first, then a payment is made.</p><p>Compare Plan A, a fixed $160 monthly payment, with Plan B, a fixed $300 monthly payment. The actual final payment is limited to the remaining amount due. This classroom model uses one monthly calculation; actual card statements can use daily balances and different terms.</p><div class="formula">\[B_{k+1}=1.015B_k-M,\qquad B_0=8000,\]</div><p>where M is the fixed scheduled payment while a full payment is still needed. The ending balance becomes the next month’s starting balance. For the long comparison here, the calculator keeps full internal precision and rounds its displayed results to cents. That preserves the original calculation method for this application.</p></section>'''+progress()+r'''
<section class="card" data-check-group="1"><div class="kicker">Part 1 / Compute before using the calculator</div><h2>What happens in the first month?</h2><p>Both plans begin with the same balance and rate. Calculate interest before subtracting either payment. Principal reduction is the payment minus interest; it is not the same as the whole payment.</p><div class="grid">'''+num('a1','Plan A: first-month interest ($)',120,'Multiply 8000 by 0.015.',.02)+num('a2','Plan A: first payment’s principal reduction ($)',40,'Subtract interest from the $160 payment.',.02)+num('a3','Plan A: balance after the first payment ($)',7960,'Add first interest to 8000, then subtract 160.',.02)+num('b1','Plan B: first-month interest ($)',120,'The starting balance and rate match Plan A before either payment.',.02)+num('b2','Plan B: first payment’s principal reduction ($)',180,'Subtract interest from the $300 payment.',.02)+num('b3','Plan B: balance after the first payment ($)',7820,'Add first interest to 8000, then subtract 300.',.02)+r'''</div>'''+written('repayFirstReason','Explain why the interest charges agree but the principal reductions do not. Predict which plan will have less interest in month 2, and calculate both charges.')+check()+r'''</section>
<section class="card"><div class="kicker">Part 2 / Repeat the rule</div><h2>Trace both plans all the way to payoff</h2><p>Predict which plan takes longer and which has greater total interest, then run the calculation. It repeats the same monthly update you used by hand, reducing the final actual payment when the remaining due is smaller than M.</p><div class="actions"><button type="button" id="run">Calculate both repayment plans</button></div><div id="appResults" hidden><div class="stats"><div class="stat"><span>Plan A payoff</span><output id="aMonths"></output></div><div class="stat"><span>Plan A total interest</span><output id="aInt"></output></div><div class="stat"><span>Plan B payoff</span><output id="bMonths"></output></div><div class="stat"><span>Plan B total interest</span><output id="bInt"></output></div></div><div class="chart" id="repayPlot"></div><div class="table-wrap" id="repayTotals"></div><div class="controls"><div><label for="repayPlan">Inspect a plan’s table</label><select id="repayPlan"><option value="A">Plan A — $160 per month</option><option value="B">Plan B — $300 per month</option></select></div></div><p class="small">The trace shows the first six months and the payoff month. Dollar values are rounded for display; calculations retain precision. The payoff month’s actual payment can be smaller than the schedule.</p><div class="table-wrap" id="repayTrace"></div></div><noscript><p>The calculation controls need JavaScript. The static figure below and the explorer link give the same starting comparison.</p></noscript>'''+figure('card-repayment','For the hypothetical $8000 balance at 18% with full internal precision, $160 monthly payments take 94 months and $300 payments take 35. Total modeled interest is about $6897.89 and $2293.42 respectively.','The comparison holds the principal, nominal rate, payment timing, and absence of new charges fixed. The monthly commitments differ.')+r'''</section>
<section class="card" data-check-group="2"><div class="kicker">Part 3 / Compare and explain</div><h2>How does an earlier balance reduction change later interest?</h2><p>Use the payoff results to compare duration and cost. The calculator computes interest savings from unrounded totals before displaying cents. Subtracting already-rounded displayed totals can differ by one cent; that difference is accepted here.</p><div class="grid">'''+num('c1','Months saved with Plan B',59,'Subtract Plan B’s payoff month from Plan A’s.',.01)+num('c2','Total interest saved with Plan B ($)',4604.46,'Subtract the total interest under B from the total under A; a one-cent display-rounding difference is accepted.',.05)+select('c3','Why is first-month interest the same?',[('samebase','Interest is based on the same starting balance and the same monthly rate before either payment is made.'),('payment','The payment amount determines the interest charge.'),('random','The two values happen to match by coincidence.')],'samebase','Use the order of operations: interest first, payment second.')+select('c4','Why does the larger payment reduce total interest here?',[('balance','It reduces the balance faster, so later interest is calculated on a smaller amount.'),('rate','It lowers the quoted APR each month.'),('simple','It changes compound interest into simple interest.')],'balance','The rate stays fixed. Identify which input to the next interest calculation changes.')+r'''</div>'''+written('repayTradeoff','Write a comparison that includes monthly commitment, payoff time, total interest, and one model assumption. Explain the tradeoff without assuming what a borrower’s budget can support.')+check()+r'''</section>
<section class="card"><h2>Change an assumption and make a new prediction</h2><p>Suppose Plan B’s first $300 payment is followed by a new $50 purchase added to the balance after payment. The first ending balance would be $7,870 instead of $7,820. At the same 1.5% rate, next month’s interest would be $118.05 instead of $117.30. The original payoff calculation no longer describes that changed purchase history.</p>'''+written('repayAssumption','Explain why a payoff estimate based on “no new purchases” needs revision when new purchases are added. Which part of the repeated update changes?')+r'''<p>Use the <a href="../demos/interest_loans.html#repayment">loan explorer</a> to test another fixed payment or compare rounding rules. Select full internal precision to reproduce this application’s results. The cent-rounded reading uses the same interest-and-payment sequence, with a different rounding convention.</p></section>
'''
page('applications/week6_application.html','Application','How two payments reshape the same debt.','Compare a first-month calculation with a complete repayment path, then explain why later interest depends on earlier payments.',application,['Two fixed schedules','Monthly trace & total cost','Assumptions made visible'],store='math107_week6_application_v3',legacy='math107_week6_application_v2',nextlink=('Explore growth in an AI setting','applications/week6_ai.html'))

ai=r'''
<section class="card"><div class="kicker">The connection / A growth rule for a resource</div><h2>What does it mean to say an AI resource is growing?</h2><p>A computing center might describe changes in processing capacity, data volume, energy use, or service demand. “Add 25 units” and “increase by 25%” specify different rules. We can study the distinction with the same mathematics as simple and compound interest.</p><p>Imagine an index of available computing capacity that starts at 100 units. These are normalized capacity units, not a count of whole computers. All values and growth rates below are invented. The model concerns a resource used by AI services; it does not measure intelligence, learning, or answer quality.</p><div class="grid"><div><h3>Additive plan</h3><p>\(A_{k+1}=A_k+25\), starting at 100. Each year adds 25 capacity units.</p></div><div><h3>Percentage-growth plan</h3><p>\(B_{k+1}=1.25B_k\), starting at 100. Each year adds 25% of the current capacity.</p></div></div></section>
<section class="card"><h2>Trace two years before using a formula</h2>'''+table(['Year','Add 25 units per year','Grow by 25% per year'],[['0','100','100'],['1','125','125'],['2','150','156.25'],['3','175','195.3125'],['4','200','244.140625']])+r'''<p>The first changes agree because 25% of 100 is 25. In year 2, the percentage plan adds 31.25 units because its base is now 125. The additive plan continues adding 25.</p><div class="formula">\[A_k=100+25k,\qquad B_k=100(1.25)^k.\]</div><p>These rules connect the current state to the next one. A resource limit or a policy change can alter that connection; an exponential formula is a conditional model, not a prediction that growth must continue.</p></section>'''+progress()+r'''
<section class="card" data-check-group="1"><div class="kicker">Your turn / Use the familiar mathematics</div><h2>Compare an amount, a factor, and an estimate</h2><div class="grid">'''+num('q1','Start at 100, add 25 per year: amount after 4 years',200,'Use 100+25(4).',.001)+num('q2','Start at 100, grow 25% per year: amount after 2 years',156.25,'Use 100(1.25)^2.',.001)+num('q3','At 12% fixed annual percentage growth: Rule-of-72 doubling estimate (years)',6,'Compute 72/12, using the percentage number.',.001)+select('q4','If the original +25 and +25% rules continue indefinitely without a cap, which eventually grows faster?',[('Repeated percentage growth','Repeated percentage growth'),('Adding the same fixed amount','Adding the same fixed amount'),('They stay equal forever','They stay equal forever'),('There is no way to compare them','There is no way to compare them')],'Repeated percentage growth','The percentage rule’s added amount grows with its current base.')+r'''</div>'''+written('growthReason','Explain why the first-year changes agree and the second-year changes differ. Give both second-year increases in capacity units.')+check()+r'''</section>
<section class="card"><div class="kicker">Investigate / Put a ceiling in the rule</div><h2>A capacity limit changes the trajectory</h2><p>Keep both original growth plans. Add a third, hypothetical policy: capacity grows by 25% per year until it reaches a ceiling K, then remains at K. Its update is \(L_{k+1}=\min(K,1.25L_k)\), starting at 100. “Min” means choose the smaller of the two listed values.</p><div class="controls"><div><label for="growthYears">Years to compare</label><input id="growthYears" type="number" min="0" max="20" step="1" value="12"></div><div><label for="growthCap">Ceiling K (capacity units)</label><input id="growthCap" type="number" min="100" max="2000" step="1" value="400"></div></div><p id="growthSummary" class="readout" aria-live="polite"></p><div class="chart" id="growthPlot">'''+figure('ai-growth-limits','Additive growth, uncapped 25% growth, and 25% growth capped at 400 start at 100. The capped path reaches its ceiling at year 7 and remains there.','Enable JavaScript to change the horizon or ceiling and inspect the yearly values.')+r'''</div><div class="table-wrap trace" id="growthTable"></div><p class="small">Displayed capacity values are rounded; updates retain precision.</p><p>Compare years 2, 7, and 12 at K=400. When does the limited plan first differ from the uncapped percentage plan? Which assumption changed? The fixed-addition plan remains uncapped here so we can compare three explicitly different rules.</p>'''+written('growthCapReason','Explain what happens to the limited plan at its ceiling. Why would it be incorrect to continue using 100(1.25)^k for that limited process afterward?')+r'''</section>
<section class="card"><h2>Ask what the index does and does not measure</h2><p>A growing compute-capacity index does not establish that learning, reliability, or useful service grows at the same rate. Each outcome needs a defined measure and observations. A capacity ceiling also needs a physical or policy explanation if we want to use it for an actual operation.</p>'''+written('growthEvidence','Choose one possible resource limit for a computing center. Explain what measurement would help test the growth assumption, and name one important outcome that the capacity index alone would not measure.')+r'''<div class="insight"><h3>Connect Weeks 5, 6, and 7</h3><p>Week 5 focused on repeated updates and feedback. Week 6 distinguishes the patterns generated by fixed additions, percentages, and scheduled subtractions. Week 7 asks how a chosen goal changes which available plan we prefer. Naming the rule and its assumptions comes first.</p></div></section>
'''
page('applications/week6_ai.html','AI Application','Growth, capacity, and an explicit limit.','Use a hypothetical computing resource to compare fixed additions, percentage growth, and a policy that stops growth at a ceiling.',ai,['Two growth rules','A resource ceiling','Measures & evidence'],store='math107_ai_module_6_v5',legacy='math107_ai_module_6_v4',nextlink=('Prepare the loan discussion','discussions/week6_discussion.html'))

discussion=r'''
<section class="card"><div class="kicker">The task / Follow a payment through the next balance</div><h2>Show how a monthly payment changes later interest</h2><p>A hypothetical borrower has a $5,000 balance at a fixed 18% nominal annual rate. Use monthly interest i=0.18/12=0.015. Interest is added first, then the payment is applied. Assume no new purchases, fees, or rate changes.</p><p>Choose a fixed monthly payment of $150, $225, or $300 to analyze in detail. These are model choices, not statements about what anyone can afford. Your comparison should show both the monthly commitment and its consequences over time.</p><p>Work before reading classmates’ posts. Use a table, labeled calculations, graph, or organized handwritten work to communicate your reasoning. The fields below save drafts in this browser; post the finished work through your class discussion board as directed.</p></section>
<section class="card"><div class="kicker">Part A / Build the first three months by hand</div><h2>Use the new balance each time</h2><p>Write \(B_{k+1}=1.015B_k-M\) with your chosen M and starting value \(B_0=5000\). For this discussion, round each month’s interest to the nearest cent before calculating the end balance.</p>'''+table(['Month','Starting balance','Interest = start × 0.015','Actual payment','Principal reduction','Ending balance'],[['1','$5,000','Your calculation','Chosen M','Payment − interest','Start + interest − payment'],['2','Previous end','Your calculation','Chosen M','Your calculation','Your calculation'],['3','Previous end','Your calculation','Chosen M','Your calculation','Your calculation']])+r'''<p>Check that your second and third starting balances agree with the previous ending balances. The first three payments in these plans are full scheduled payments; near payoff, the final actual payment can be smaller.</p>'''+written('discussionChoice','State your chosen payment and recurrence, defining the balance, time unit, rate, and payment amount.')+written('discussionMonths','Show the first three monthly calculations, including interest, principal reduction, and ending balance. A compact table is welcome.')+r'''</section>
<section class="card"><div class="kicker">Part B / Follow the whole schedule</div><h2>Connect the hand calculation to the explorer</h2><p>Open the <a href="../demos/interest_loans.html#repayment">loan explorer</a> and choose the discussion preset. Enter your selected payment, keep monthly cent rounding, and use a long enough horizon to reach payoff. Compare the first three rows with your hand work before recording the totals.</p><ol class="steps"><li>Record the payoff month, actual last payment, total paid, and total interest.</li><li>Verify total interest equals total paid minus the $5,000 starting principal.</li><li>Explain why all three choices have the same first interest charge.</li><li>Use a later starting balance to explain why their subsequent interest charges differ.</li><li>Describe the tradeoff between monthly payment size and the duration and cost of this modeled debt.</li></ol>'''+written('discussionTotals','Record the full-schedule results, verify the interest total, and explain how the first three rows connect to the long-run result.')+written('discussionTradeoff','Write your comparison in context, with a stated assumption and a monthly-versus-long-run tradeoff.')+r'''</section>
<section class="card"><h2>Reply by testing a mathematical claim</h2><p>Compare with a classmate’s payment choice, or investigate a second amount yourself. Check one of their monthly rows, then compare payoff time and total interest under the same rounding convention. Explain the difference through the changing balances.</p><p>For another specific test, consider a $75 payment at the original $5,000 balance. Predict whether the debt initially grows, stays fixed, or shrinks. Use that prediction to explain why “a payment was made” does not by itself imply progress toward payoff under a stated interest rule.</p>'''+written('discussionReply','Draft a reply that checks a calculation or develops the $75-payment test. Use a balance update to support the explanation.')+r'''</section>
<section class="card"><h2>Review before posting</h2><ul><li>I identified the annual percentage and the monthly decimal rate.</li><li>My table carries each ending balance into the next month.</li><li>I distinguished interest, actual payment, and principal reduction.</li><li>I used monthly cent rounding for both hand work and the explorer.</li><li>I reported a payoff only after the balance reached zero.</li><li>My comparison states its assumptions and contributes mathematical reasoning.</li></ul><p>Your drafts save and print, but this page does not grade or submit them. Add your name below if you want a completed copy for your records.</p></section>
'''
page('discussions/week6_discussion.html','Discussion','A payment changes more than one month.','Build three loan updates, verify a complete schedule, and explain how payment size shapes later balances and interest.',discussion,['Three payment choices','A hand table & full schedule','Saved drafts & reply scaffold'],store='math107_week6_discussion_v1',nextlink=('Continue to Week 7','readings/week7_reading.html'))

